import {CHECKED_AT,eventLabel} from './official-schedule.js';
import {sourceHtml} from './schedule-ui.js';
import {matchExams,scheduleConflicts,normalizeSchoolPlans} from './guide-model.js';
import {dayDiff,shiftMonth,jstToday} from './calendar.js';
export const guideCopy={
 decided:{heading:'受けたい試験が決まったら',intro:'まずは、申し込みの締切と試験日を確かめておきましょう。受ける級や方式まで確認できると、そのあとの準備も進めやすくなります。',eyebrow:'日程・申し込みを確かめたい方へ',alt:'相談員と申し込みの書類を確かめる女性'},
 discover:{heading:'何を学ぼうか、迷っている方へ',intro:'仕事に役立てたい、英語を学び直したい。まだ試験の名前が決まっていなくても大丈夫です。気になることや受けられそうな時期から、少し見てみませんか。',eyebrow:'資格をこれから選びたい方へ',alt:'本を見ながら学びたい分野を相談する大人たち'},
 compare:{heading:'いくつか受けたい試験がある方へ',intro:'受けたい試験を並べて、予定が合うか確かめてみましょう。締切と試験日の間にどれくらい時間があるかも、まとめて見られます。',eyebrow:'複数の試験を予定している方へ',alt:'二冊の手帳を並べて受験日を比べる二人'},
 family:{heading:'お子さんと、これからの予定を',intro:'受験の日が近づくと、気になることも増えますね。ご本人と一緒に、出願から入学手続きまでの日程や、準備しておきたいことを確かめていきましょう。',eyebrow:'入試を支える保護者の方へ',alt:'お子さんの話を聞きながら入試の予定を確認する母親'},
 prepared:{heading:'申し込みが済んだら、当日の支度を',intro:'申し込み、おつかれさまでした。受験票や持ち物、会場までの道順など、気になることを少しずつ確かめておきましょう。確認したことは、チェックして残せます。',eyebrow:'試験を控えている方へ',alt:'受験票や筆記用具をかばんにそろえる女性'}
};
let pageAbort;
export function mountGuide(id,params,context){
 pageAbort?.abort();pageAbort=new AbortController();const signal=pageAbort.signal;
 const {state,exams,events,types,guides,esc,formatDate,examCard,eventSummary,checklist,updateProgress,toast}=context;
 const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));const root=$('#guide-content');
 const on=(node,event,callback)=>node?.addEventListener(event,callback,{signal});
 const meta=guideCopy[id];const cat=guides.find(g=>g.id===id);
 $('#guide-page').classList.add('enhanced-guides');$('#guide-page').dataset.guide=id;
 $('#guide-title').textContent=meta.heading;$('#guide-intro').textContent=meta.intro;$('.guide-eyebrow').textContent=meta.eyebrow;
 $('#guide-art').className='guide-illustration';$('#guide-art').innerHTML=`<img src="/assets/guide-${id}.webp" alt="${meta.alt}" width="1536" height="1024" decoding="async">`;$('#guide-art').removeAttribute('aria-hidden');
 $('#guide-links').innerHTML=guides.filter(g=>g.id!==id).map(g=>`<a href="#/guide/${g.id}"><span>${g.title}</span><small>${g.sub}</small><b aria-hidden="true">›</b></a>`).join('');
 const badge=e=>`<span class="event-type ${types[e.type].class}">${eventLabel(e)}${e.planned?'（予定）':''}</span>`;
 const note='<p class="guide-sample">掲載日程は主催者の公式情報で確認しています。確認日は各日程の出典欄に掲載しています。対象の実施回・受験区分と出典は、各詳細ページでご覧いただけます。</p>';
 const sectionHead=(title,sub='')=>`<div class="g-section-heading"><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>`;
 const faq=(items)=>`<section class="g-faq">${sectionHead('気になることは、こちらもご覧ください')}${items.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>`;
 const adviser=(title,text)=>`<aside class="g-adviser"><span class="adviser-mark" aria-hidden="true">ひとこと</span><h3>${title}</h3><p>${text}</p></aside>`;
 const roadmap=(items)=>`<ol class="g-roadmap">${items.map(([title,text],i)=>`<li><span class="roadmap-number">${i+1}</span><div><h3>${title}</h3><p>${text}</p></div></li>`).join('')}</ol>`;
 const cards=items=>items.map(e=>`<div class="g-exam-wrap"><div class="g-card-meta"><span>${e.field}</span><span>${e.id==='boki'?'第174回・統一試験':e.id==='eiken'?'個人・従来型・本会場':'日程を確認'}</span></div>${examCard(e)}</div>`).join('');
 const fieldOptions='<option value="all">すべての分野</option>'+[...new Set(exams.filter(e=>!['大学入試','高校入試'].includes(e.field)).map(e=>e.field))].map(f=>`<option>${f}</option>`).join('');
 const periods='<option value="all">時期を決めずに見る</option>'+[...new Set(events.filter(e=>e.type==='exam').map(e=>e.date.slice(0,7)))].sort().map(m=>`<option value="${m}">${Number(m.slice(0,4))}年${Number(m.slice(5))}月</option>`).join('');
 if(id==='decided'||id==='discover'){
  const decided=id==='decided';
  root.innerHTML=`${decided?roadmap([['日程を探す','試験名から、締切と試験日を確認。'],['受け方を確かめる','級・方式・申込先を確認。'],['予定に残す','保存して、あとから見返せます。']]):`<section class="g-purpose-section">${sectionHead('どんなことが気になっていますか','ひとつ選んでみても、分野を決めずに眺めても大丈夫です。')}<div class="g-purpose"><button data-purpose="work" aria-pressed="false"><span>仕事に役立てたい</span><small>会計・金融などを見てみる</small><b>›</b></button><button data-purpose="language" aria-pressed="false"><span>英語を学び直したい</span><small>語学の試験を見てみる</small><b>›</b></button><button data-purpose="all" aria-pressed="true"><span>まだ決めずに見たい</span><small>いろいろな分野から探す</small><b>›</b></button></div></section>`}
  <div class="g-search-layout"><section class="g-search-main"><div class="g-search-panel"><h2>${decided?'受けたい試験の名前を入れてみてください':'受けられる時期も、合わせてみましょう'}</h2><form class="search-form" id="guide-search"><label class="sr-only" for="guide-q">試験名</label><span class="search-icon" aria-hidden="true"></span><input type="search" id="guide-q" placeholder="例：TOEIC、英検、簿記" autocomplete="off"><button class="primary" type="submit">検索</button></form>${decided?'<div class="g-popular"><span>試験名から</span><button data-query="TOEIC">TOEIC</button><button data-query="英検">英検</button><button data-query="簿記">日商簿記</button></div>':''}<div class="g-select-row"><label>分野<select id="field-select">${fieldOptions}</select></label><label>試験のある月<select id="period-select">${periods}</select></label><button class="g-reset" id="guide-reset">条件を戻す</button></div></div><div class="g-results-header"><h2>${decided?'日程を確かめましょう':'気になる試験はありますか'}</h2><p id="guide-results-count" aria-live="polite"></p></div>${note}<div id="guide-exams" class="exam-cards"></div></section><div class="g-sidebar">${adviser(decided?'申し込む前に、もうひとつ':'選ぶ前に、確かめたいこと',decided?'同じ試験でも、級や受け方が違うと、申し込み先や日程が変わることがあります。ご自身が受ける回の案内か、最後に確かめておいてくださいね。':'受験資格や受験料、会場に行ける日なども大切です。気になった試験があったら、まずは受け方と日程を見てみましょう。')}<section class="g-side-list"><h3>${decided?'ここも見ておくと安心です':'比べるときの目安に'}</h3><ul><li>${decided?'締切の日付と時刻':'受験資格があるか'}</li><li>${decided?'郵送なら「必着」か「消印有効」か':'会場や試験方式が合うか'}</li><li>${decided?'支払いと受付完了の確認':'準備に使える時間があるか'}</li></ul><button class="text-button" data-article="method">受け方の違いを確認する ›</button></section><a class="g-next-link" href="#/guide/compare"><strong>気になる試験が、いくつかある方へ</strong><span>日程を並べて比べられます ›</span></a></div></div>
  ${faq(decided?[[ 'まだ申込期間が分からないときは？','試験日が出ていても、申し込みの案内はあとから出ることがあります。推測で予定を入れず、主催者の発表を確かめておきましょう。'],['試験を保存したら、申し込みも済みますか？','保存は、ご自身の予定を見返すための機能です。申し込みや支払いは、主催者の案内に沿って別に行ってくださいね。']]:[['どれを選べばよいか、まだ迷っています。','最初からひとつに決めなくても大丈夫です。気になった試験を保存して、日程や受け方を比べるところから始めてみませんか。'],['通年で受けられる試験もありますか？','CBTなど、日時や会場を選べる試験もあります。ここに掲載していない方式もあるので、詳細ページから主催者の案内を確認してみてください。']])}`;
  let purpose='all',limit=6;
  const update=()=>{const found=matchExams(exams,events,{query:$('#guide-q').value,field:$('#field-select').value,period:$('#period-select').value,purpose});$('#guide-results-count').textContent=`${found.length}件の試験`;$('#guide-exams').innerHTML=found.length?cards(found.slice(0,limit))+(found.length>limit?'<button class="quiet-button" id="guide-more">次の6件も見る</button>':''):'<div class="g-empty"><h3>この条件に合う掲載試験はありませんでした。</h3><p>分野や時期を少し変えて、もう一度探してみてくださいね。ここにない試験もあります。</p><button class="quiet-button" id="empty-reset">条件を戻して見る</button></div>';};
  const reset=()=>{$('#guide-q').value='';$('#field-select').value='all';$('#period-select').value='all';purpose='all';$$('[data-purpose]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.purpose==='all')));update();};
  on($('#guide-search'),'submit',e=>{e.preventDefault();update();});on($('#guide-q'),'input',update);on($('#guide-q'),'change',update);on($('#field-select'),'change',update);on($('#period-select'),'change',update);
  on(root,'click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='guide-more'){limit+=6;update();}else limit=6;if(b.dataset.query){$('#guide-q').value=b.dataset.query;update();}if(b.dataset.purpose){purpose=b.dataset.purpose;$('#field-select').value='all';$$('[data-purpose]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));update();}if(b.id==='guide-reset'||b.id==='empty-reset')reset();});update();
 }else if(id==='compare'){
  const included=exams.filter(x=>!['大学入試','高校入試'].includes(x.field));
  root.innerHTML=`${roadmap([['試験を選ぶ','保存した試験や気になる試験を。'],['予定を並べる','締切と試験日を見渡せます。'],['重なりを確かめる','仕事やご家族の予定とも照らして。']])}<section class="g-choose-panel">${sectionHead('比べたい試験を選んでください','保存した試験には、はじめからチェックが入っています。')}<label>試験名・実施回で絞り込む<input id="compare-query" type="search" placeholder="例：TOEIC、漢検"></label><div class="compare-select">${included.map(e=>`<label><input type="checkbox" data-compare="${e.id}" ${state.saved.includes(e.id)?'checked':''}><span>${e.short}<small>${e.edition}</small></span></label>`).join('')}</div><div class="g-comparison-controls"><button class="quiet-button" id="compare-demo">3つの試験で比べてみる</button><button class="text-button" id="compare-clear">選択を外す</button><label>表示する期間<select id="compare-range">${[...new Set(events.map(e=>e.date.slice(0,7)))].sort().map(m=>`<option value="${m}" ${m==='2026-11'?'selected':''}>${m.replace('-','年')}月から3か月</option>`).join('')}</select></label></div></section><section><div class="g-results-header"><h2>申し込みから試験までの予定</h2><p id="compare-count" aria-live="polite"></p></div>${note}<div id="comparison" aria-live="polite"></div></section>${adviser('日にちが重なっていなくても','会場への移動や、直前の準備に使う時間も気になりますね。ご自身のカレンダーと見比べながら、無理のない予定か確かめてみてください。')}<div class="g-bottom-actions"><a class="primary" href="#/guide/decided">ほかの試験も探す ›</a><a class="quiet-button" href="#saved-section">保存した試験を見る ›</a></div>`;
  const update=()=>{const ids=$$('[data-compare]:checked').map(c=>c.dataset.compare);$('#compare-count').textContent=ids.length?`${ids.length}つの試験を表示中`:'試験を選ぶと、ここに予定が表示されます。';if(!ids.length){$('#comparison').innerHTML='<div class="g-empty"><h3>まずは、気になる試験を選んでみませんか。</h3><p>使い方を見たい方は「3つの試験で比べてみる」から試せます。</p></div>';return;}const [year,month]=$('#compare-range').value.split('-').map(Number);const months=Array.from({length:3},(_,i)=>{const x=shiftMonth(year,month-1,i);return {label:`${x.year}年${x.month+1}月`,key:`${x.year}-${String(x.month+1).padStart(2,'0')}`};});const conflicts=scheduleConflicts(events,ids);const selected=events.filter(e=>ids.includes(e.exam));$('#comparison').innerHTML=`${conflicts.map(c=>`<div class="g-conflict"><h3>${formatDate(c.date)}は、試験日が重なっています。</h3><p>${c.names.join('と')}。試験時間や会場も、主催者の案内で確認しておきましょう。</p></div>`).join('')}<div class="g-month-agendas">${months.map(m=>{const list=selected.filter(e=>e.date.startsWith(m.key)).sort((a,b)=>a.date.localeCompare(b.date));return `<section><h3>${m.label}</h3>${list.length?list.map(e=>`<button class="g-agenda-event" data-event="${e.id}"><span class="agenda-day">${Number(e.date.slice(-2))}<small>日</small></span><span>${badge(e)}<strong>${e.short}</strong>${e.time?`<small>${e.time}${e.type==='deadline'?'まで':''}</small>`:''}${e.note?`<small>${e.note}</small>`:''}</span><b>›</b></button>`).join(''):'<p class="g-month-empty">この月に掲載している予定はありません。</p>'}</section>`;}).join('')}</div><div class="g-comparison-detail">${sectionHead('選んだ試験の日程を、一覧でも')}<table class="compare-table"><thead><tr><th scope="col">試験</th><th scope="col">申込締切</th><th scope="col">試験日</th><th scope="col">結果発表など</th></tr></thead><tbody>${exams.filter(e=>ids.includes(e.id)).map(e=>`<tr><th scope="row"><button class="text-button" data-exam="${e.id}">${e.name}<small>${e.edition}</small> ›</button></th><td data-label="申込締切">${eventSummary(e.id,'deadline')}</td><td data-label="試験日">${eventSummary(e.id,'exam')}</td><td data-label="結果発表など">${eventSummary(e.id,'result')}</td></tr>`).join('')}</tbody></table></div>`;};
  on($('#compare-query'),'input',e=>{$$('[data-compare]').forEach(c=>{c.closest('label').hidden=!c.closest('label').textContent.toLocaleLowerCase('ja').includes(e.target.value.toLocaleLowerCase('ja'));});});
  on(root,'change',e=>{if(e.target.matches('[data-compare],#compare-range'))update();});on($('#compare-demo'),'click',()=>{$$('[data-compare]').forEach(c=>c.checked=['toeic','fp','eiken'].includes(c.dataset.compare));update();});on($('#compare-clear'),'click',()=>{$$('[data-compare]').forEach(c=>c.checked=false);update();});update();
 }else if(id==='family'){
  let plans=[];try{plans=normalizeSchoolPlans(JSON.parse(localStorage.getItem('michi-school-plans')||'[]'));}catch{}
  const phases={apply:'出願締切',exam:'試験日',result:'合格発表',enroll:'入学手続きの締切'};
  root.innerHTML=`<section>${sectionHead('出願から入学まで、順番に見てみましょう')}<div class="family-steps"><article class="family-step"><span>01</span><h3>出願</h3><p>必要な書類、提出先、支払いの期限を確かめましょう。</p><small>学校ごとの募集要項を確認</small></article><article class="family-step"><span>02</span><h3>試験</h3><p>受験票や持ち物、会場への行き方も、ご本人と一緒に。</p><small>集合時刻も確かめておきたいですね</small></article><article class="family-step"><span>03</span><h3>合格発表</h3><p>確認する日時と方法を、先に見ておきましょう。</p><small>学校・選抜方式ごとに確認</small></article><article class="family-step"><span>04</span><h3>入学手続き</h3><p>書類と納付の締切は、別の日になっていないでしょうか。</p><small>合格後の案内も確認</small></article></div></section><div class="g-family-reference"><section><h2>入試の日程を探す</h2><div class="g-family-tabs" role="group" aria-label="入試の種類"><button data-family-type="university" aria-pressed="true">大学入試</button><button data-family-type="highschool" aria-pressed="false">高校入試</button></div><div id="family-reference"></div></section>${adviser('予定は、ご本人と一緒に','準備の進め方は、ご家庭によってさまざまです。気になる日を一緒に見て、どこを手伝ってほしいか聞いてみるところからでもよいですね。')}</div>
  <section class="g-school-section">${sectionHead('学校ごとの予定を、ひとつに','募集要項などで確かめた日を、メモしておけます。')}<p class="g-personal-label">ご自身で入力する予定メモ・このブラウザに保存</p><form id="school-plan-form"><label class="g-school-name">学校名・試験名<input name="school" id="school-name" maxlength="100" required placeholder="例：○○大学 一般選抜"></label><div class="g-school-dates">${Object.entries(phases).map(([k,v])=>`<label>${v}<input name="${k}" type="date" min="2000-01-01" max="2100-12-31"></label>`).join('')}</div><p class="small-note">日付は分かるところだけで大丈夫です。最低ひとつ入力してください。</p><p id="school-error" role="alert"></p><button class="primary" type="submit">予定メモに追加する</button></form><div id="school-plans" aria-live="polite"></div><p class="small-note">公式の日程データとは別の、ご自身のメモです。別の端末には引き継がれません。</p></section>
  <section>${sectionHead('ご家族で、ここも確かめておきませんか')}${checklist('family',[['必要な書類をそろえる','発行に時間がかかる書類もあります。学校の案内を見ながら、余裕をもってそろえましょう。'],['会場までの行き方を調べる','交通手段や集合時刻を、ご本人と一緒に確認しておきたいですね。'],['入学手続きの期限を確認する','合格発表のあとにも期限があります。出願先が複数あるときは、並べて見ておきましょう。']])}</section>`;
  const reference=(type)=>{$$('[data-family-type]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.familyType===type)));const found=exams.filter(e=>e.field===(type==='university'?'大学入試':'高校入試'));$('#family-reference').innerHTML=`<div class="g-reference-card"><h3>${type==='university'?'大学・選抜方式から選ぶ':'お住まいの地域から選ぶ'}</h3><p>同じ学校でも、選抜の種類で日程が変わります。受ける区分を確かめながらご覧くださいね。</p><label>日程を確認する<select id="family-exam-select"><option value="">選んでください</option>${found.map(e=>`<option value="${e.id}">${esc(e.name)}／${esc(e.edition)}</option>`).join('')}</select></label><p class="small-note">学校に提出する期限は、県の受付締切より早い場合があります。</p></div>`;};
  on(root,'change',e=>{if(e.target.id==='family-exam-select'&&e.target.value)location.hash='#/exam/'+e.target.value;});
  const renderPlans=()=>{$('#school-plans').innerHTML=plans.length?plans.map(p=>`<article class="g-school-plan"><div><span class="g-personal-label">ご自身の予定メモ</span><h3>${esc(p.name)}</h3></div><dl>${Object.entries(phases).map(([k,label])=>`<div><dt>${label}</dt><dd>${p.dates[k]?formatDate(p.dates[k],true):'未入力'}</dd></div>`).join('')}</dl><button class="text-button" data-remove-school="${esc(p.id)}">このメモを取り消す</button></article>`).join(''):'<div class="g-empty"><h3>まだ予定のメモはありません。</h3><p>出願先が決まってきたら、分かる日から入れてみてくださいね。</p></div>';};
  const savePlans=()=>{try{localStorage.setItem('michi-school-plans',JSON.stringify(plans));}catch{toast('このブラウザでは保存できません。画面を開いている間は確認できます。');}};
  on($('#school-plan-form'),'submit',e=>{e.preventDefault();const f=new FormData(e.target);const name=String(f.get('school')||'').trim();const dates=Object.fromEntries(Object.keys(phases).map(k=>[k,String(f.get(k)||'')]));$('#school-error').textContent='';if(!name||!Object.values(dates).some(Boolean)){$('#school-error').textContent='学校名と、分かる日付をひとつ以上入れてくださいね。';return;}if(plans.length>=20){$('#school-error').textContent='保存できるメモは20件までです。不要なメモを取り消してから追加してください。';return;}const normalized=normalizeSchoolPlans([{id:'school-'+Date.now(),name,dates}]);if(!normalized.length||!Object.values(normalized[0].dates).some(Boolean)){$('#school-error').textContent='日付をもう一度確かめておいてください。';return;}plans.push(normalized[0]);savePlans();renderPlans();e.target.reset();toast('予定メモに追加しました。');});
  on(root,'click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.familyType)reference(b.dataset.familyType);if(b.dataset.removeSchool){plans=plans.filter(p=>p.id!==b.dataset.removeSchool);savePlans();renderPlans();toast('予定メモを取り消しました。');}});reference('university');renderPlans();
 }else if(id==='prepared'){
  const chosen=exams.find(e=>e.id===params.get('exam'))||exams.find(e=>e.id===state.saved[0])||exams.find(e=>e.id==='boki');
  root.innerHTML=`<section class="g-prep-selected"><div class="g-prep-header"><h2>どの試験の準備を確認しますか</h2><label class="sr-only" for="prepared-select">受ける試験</label><select id="prepared-select">${exams.map(e=>`<option value="${e.id}" ${chosen.id===e.id?'selected':''}>${e.name}</option>`).join('')}</select></div><div class="g-prep-exam"><div><span class="g-personal-label">ご自身の確認用</span><h2>${chosen.name}</h2><p>試験日　${eventSummary(chosen.id,'exam')}</p></div><label class="applied-label"><input type="checkbox" data-applied="${chosen.id}" ${state.applied.includes(chosen.id)?'checked':''}>申し込みを済ませた</label></div>${note}</section>
  <section class="g-prep-workspace"><div class="g-prep-tabs" role="group" aria-label="確認するタイミング"><button data-prep-stage="before" aria-pressed="true">試験までに</button><button data-prep-stage="after" aria-pressed="false">試験のあとに</button></div><div class="g-prep-layout"><div><div class="g-results-header"><h2 id="prep-check-heading">当日までに、ひとつずつ</h2><span class="g-progress-pill" id="prep-progress" aria-live="polite"></span></div><div id="prep-checks"></div></div><div>${adviser('持ち物は、試験ごとに違います','ここでは共通して気にかけたいことをご案内しています。使える筆記用具や本人確認書類は、最後に必ず主催者の案内と照らし合わせてくださいね。')}<div class="g-side-list"><h3>予定も、手元に残しておきませんか</h3><p>試験日や結果発表日を確認できます。詳細ページから、出典と確認日を添えた予定ファイルも保存できます。</p><button class="primary" data-exam="${chosen.id}">日程・結果発表を確認 ›</button></div></div></div></section>
  ${faq([['受験票が見当たらないときは？','再発行や問い合わせ先は試験ごとに異なります。申込完了のお知らせや、主催者の受験案内にある連絡先を確認してくださいね。'],['このチェックを付けると、申し込みも完了しますか？','チェックは、ご自身が確かめたことを残すためのものです。申し込み・支払い・主催者への連絡は行われません。']])}`;
  const before=[['受験票を確認する','印刷や写真の貼付が必要か、主催者の案内で確かめておきましょう。'],['会場までの行き方を調べる','集合時刻に間に合うように、出発する時間も決めておきたいですね。'],['持ち物をそろえる','本人確認書類や筆記用具など、公式の持ち物案内とひとつずつ照らし合わせましょう。'],['当日の予定を家族や職場と共有する','必要な方だけで大丈夫です。移動やお迎えなど、お願いしたいことがあれば早めに。']];
  const after=[['結果を確認する日と方法を確かめる','Webでの発表や通知の発送日など、主催者の案内を見ておきましょう。'],['合格後の手続きがあるか確認する','登録や証明書の申請が必要な試験もあります。案内に沿って確かめておいてくださいね。'],['次の予定を整理する','仕事や進学先に結果を提出する場合は、必要な書類や期限も確認しておきましょう。']];
  const progress=()=>{const all=$$('[data-check]'),done=all.filter(x=>x.checked).length;$('#prep-progress').textContent=`${done} / ${all.length} 確認済み`;updateProgress();};
  const stage=which=>{$$('[data-prep-stage]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.prepStage===which)));$('#prep-check-heading').textContent=which==='before'?'当日までに、ひとつずつ':'試験のあとも、忘れずに';$('#prep-checks').innerHTML=checklist(which==='before'?chosen.id:chosen.id+'-after',which==='before'?before:after);progress();};
  on($('#prepared-select'),'change',e=>location.hash='#/guide/prepared?exam='+e.target.value);on(root,'click',e=>{const b=e.target.closest('[data-prep-stage]');if(b)stage(b.dataset.prepStage);});on(root,'change',e=>{if(e.target.matches('[data-check]'))progress();});stage('before');
 }
 updateProgress();
}
